/**
 * Claude lifecycle reporter (Spec 1595).
 *
 * Every Claude agent Codev launches reports its lifecycle to Tower so the
 * overview can serve working / needs-input / idle from the harness itself
 * instead of inferring it from PTY silence. This module is the single source of
 * truth for the Claude provider's reporter, in the shape of the write-guard
 * (`worktree-write-guard.ts`): two generated files, installed into a
 * codev-owned directory no agent session writes to:
 *   - `claude-lifecycle-reporter.cjs`: a dependency-free Node hook script
 *   - `claude-lifecycle-reporter-settings.json`: the hook set, handed to the harness
 *     with `--settings <path>` through `CLAUDE_HARNESS.buildLifecycleReporterInjection`
 *
 * The script translates Claude hook names to the harness-neutral
 * `AgentLifecycleEvent` vocabulary, so no Claude hook name crosses the wire.
 * Identity comes only from the launch environment (`CODEV_BUILDER_WORKTREE`, or
 * `CODEV_ARCHITECT_WORKSPACE` with `CODEV_ARCHITECT_NAME`); with neither set it
 * sends nothing.
 *
 * Fail-open by construction (SC15): every hook is `async`, the script makes one
 * request with a sub-second deadline and no retry, writes nothing to stdout
 * (so it can never make a permission decision), and always exits 0. The hook
 * command is a shell wrapper that exits 0 silently even when the script is
 * missing. Neither file embeds a secret: the local key is read at hook time.
 *
 * @see codev/specs/1595-agent-attention-states-working.md
 */

import { chmodSync, mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { randomBytes } from 'node:crypto';
import { AGENT_FARM_DIR } from '@cluesmith/codev-core/constants';
import { DEFAULT_TOWER_PORT } from '@cluesmith/codev-sdk/constants';
import { logger } from './logger.js';
import { shellEscapeSingleQuote, toShellPath, type HarnessProvider } from './harness.js';

/**
 * Basename of the installed reporter script. Both files read Claude's hook payloads and settings
 * format, so their names carry the harness: another harness's reporter installs beside them under
 * its own names, never over them.
 */
export const LIFECYCLE_REPORTER_SCRIPT_NAME = 'claude-lifecycle-reporter.cjs';

/** Basename of the installed settings file carrying the hook set. */
export const LIFECYCLE_REPORTER_SETTINGS_NAME = 'claude-lifecycle-reporter-settings.json';

/** Seconds the harness allows each hook before abandoning it. The script itself finishes well inside it. */
export const LIFECYCLE_HOOK_TIMEOUT_SECONDS = 3;

/** Claude's question tool: the PreToolUse matcher and the script's question-kind test both read it. */
export const CLAUDE_QUESTION_TOOL = 'AskUserQuestion';

/** The directory both files are installed into. */
export function lifecycleReporterDir(): string {
  return join(AGENT_FARM_DIR, 'hooks');
}

/**
 * The self-contained Node reporter script, written verbatim to the hooks
 * directory. A string constant so it ships with the compiled package; the unit
 * test writes it to a temp file and runs it with fixture stdin, so the
 * constant is the tested artifact.
 */
export const LIFECYCLE_REPORTER_SCRIPT = `#!/usr/bin/env node
// AUTO-GENERATED by @cluesmith/codev (Spec 1595). Do not edit;
// edit packages/codev/src/agent-farm/utils/lifecycle-reporter.ts instead.
'use strict';

const fs = require('node:fs');
const http = require('node:http');
const os = require('node:os');
const path = require('node:path');

const QUESTION_TOOL = '${CLAUDE_QUESTION_TOOL}';
const DEFAULT_TOWER_PORT = ${DEFAULT_TOWER_PORT};
const REQUEST_DEADLINE_MS = 800;
const OVERALL_DEADLINE_MS = 1500;
const MAX_BODY_BYTES = 8192;
const MAX_SESSION_ID_LENGTH = 128;
const MAX_TOOL_LENGTH = 64;
const MAX_SUMMARY_LENGTH = 200;

function done() {
  process.exit(0);
}

// Single line, control characters removed, at most maxLength UTF-16 units
// without splitting a surrogate pair. Empty means "omit the field".
function plainText(value, maxLength) {
  if (typeof value !== 'string') return '';
  let text = value
    .replace(/\\s*[\\r\\n\\u2028\\u2029]+\\s*/g, ' ')
    .replace(/\\t/g, ' ')
    .replace(/[\\u0000-\\u001f\\u007f-\\u009f]/g, '')
    .trim();
  if (text.length > maxLength) {
    text = text.slice(0, maxLength);
    const last = text.charCodeAt(text.length - 1);
    if (last >= 0xd800 && last <= 0xdbff) text = text.slice(0, -1);
  }
  return text;
}

// The tool's primary argument: a command's text, a path, a pattern, a URL,
// or the question being asked.
function primaryArgument(toolName, toolInput) {
  if (!toolInput || typeof toolInput !== 'object') return '';
  if (toolName === QUESTION_TOOL) {
    const questions = toolInput.questions;
    if (Array.isArray(questions) && questions[0] && typeof questions[0].question === 'string') {
      return questions[0].question;
    }
    return '';
  }
  const keys = ['command', 'file_path', 'notebook_path', 'path', 'url', 'pattern', 'query', 'description', 'prompt'];
  for (const key of keys) {
    if (typeof toolInput[key] === 'string' && toolInput[key]) return toolInput[key];
  }
  return '';
}

function needsInputDetail(input) {
  const toolName = typeof input.tool_name === 'string' ? input.tool_name : '';
  const detail = { kind: toolName === QUESTION_TOOL ? 'question' : 'permission' };
  const tool = plainText(toolName, MAX_TOOL_LENGTH);
  if (tool) detail.tool = tool;
  const summary = plainText(primaryArgument(toolName, input.tool_input), MAX_SUMMARY_LENGTH);
  if (summary) detail.summary = summary;
  return detail;
}

// Claude hook payload -> neutral { event, needsInput?, backgroundWork? }, or null.
function translate(input) {
  switch (input.hook_event_name) {
    case 'SessionStart':
      return { event: 'session-started' };
    case 'UserPromptSubmit':
      return { event: 'turn-started' };
    case 'PostToolUse':
      return { event: 'tool-activity' };
    case 'PreToolUse':
      if (input.tool_name !== QUESTION_TOOL) return null;
      return { event: 'needs-input', needsInput: needsInputDetail(input) };
    case 'PermissionRequest':
      return { event: 'needs-input', needsInput: needsInputDetail(input) };
    case 'Notification':
      if (input.notification_type === 'permission_prompt') return { event: 'needs-input' };
      if (input.notification_type === 'elicitation_dialog') return { event: 'needs-input', needsInput: { kind: 'question' } };
      if (input.notification_type === 'idle_prompt') return { event: 'turn-ended' };
      return null;
    case 'Stop': {
      const tasks = input.background_tasks;
      return { event: 'turn-ended', backgroundWork: Array.isArray(tasks) && tasks.length > 0 };
    }
    default:
      return null;
  }
}

function launchIdentity() {
  const env = process.env;
  if (env.CODEV_BUILDER_WORKTREE) {
    return { kind: 'builder', worktreePath: env.CODEV_BUILDER_WORKTREE };
  }
  if (env.CODEV_ARCHITECT_WORKSPACE && env.CODEV_ARCHITECT_NAME) {
    return { kind: 'architect', workspacePath: env.CODEV_ARCHITECT_WORKSPACE, name: env.CODEV_ARCHITECT_NAME };
  }
  return null;
}

function towerKey() {
  const override = (process.env.CODEV_TOWER_KEY || '').trim();
  if (override) return override;
  const dir = process.env.CODEV_AGENT_FARM_DIR
    ? path.resolve(process.env.CODEV_AGENT_FARM_DIR)
    : path.join(os.homedir(), '.agent-farm');
  try {
    return fs.readFileSync(path.join(dir, 'local-key'), 'utf8').trim();
  } catch (e) {
    return '';
  }
}

function towerPort() {
  const port = Number.parseInt(process.env.CODEV_TOWER_PORT || '', 10);
  if (Number.isInteger(port) && port > 0 && port < 65536) return port;
  return DEFAULT_TOWER_PORT;
}

function post(body, key) {
  const req = http.request({
    host: '127.0.0.1',
    port: towerPort(),
    path: '/api/agent-lifecycle',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(body),
      'codev-tower-key': key,
    },
  }, (res) => {
    res.resume();
    res.on('end', done);
    res.on('error', done);
  });
  req.on('error', done);
  setTimeout(() => {
    req.destroy();
    done();
  }, REQUEST_DEADLINE_MS);
  req.end(body);
}

function main(raw) {
  const at = Date.now();
  let input;
  try {
    input = JSON.parse(raw);
  } catch (e) {
    return done();
  }
  if (!input || typeof input !== 'object') return done();

  const agent = launchIdentity();
  if (!agent) return done();

  const sessionId = input.session_id;
  if (typeof sessionId !== 'string' || !sessionId || sessionId.length > MAX_SESSION_ID_LENGTH) return done();

  const translated = translate(input);
  if (!translated) return done();

  const key = towerKey();
  if (!key) return done();

  const event = { agent: agent, sessionId: sessionId, event: translated.event, at: at };
  if (translated.needsInput) event.needsInput = translated.needsInput;
  if (translated.backgroundWork !== undefined) event.backgroundWork = translated.backgroundWork;

  const body = JSON.stringify(event);
  if (Buffer.byteLength(body) > MAX_BODY_BYTES) return done();
  post(body, key);
}

// A stdin that never closes must not keep the hook alive.
setTimeout(done, OVERALL_DEADLINE_MS).unref();

let buf = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', (d) => {
  buf += d;
});
process.stdin.on('error', done);
process.stdin.on('end', () => {
  try {
    main(buf);
  } catch (e) {
    done();
  }
});
`;

/**
 * The hook command, identical for every agent. A shell wrapper rather than a
 * bare `node <path>`, so a deleted script, a missing `node` or a crash
 * produces no output and exit 0.
 */
export function buildLifecycleHookCommand(scriptPath: string): string {
  const script = `'${shellEscapeSingleQuote(toShellPath(scriptPath))}'`;
  return `[ -f ${script} ] && node ${script} >/dev/null 2>&1; exit 0`;
}

/** The settings document wiring the reporter onto every Claude hook it translates. */
export function buildLifecycleReporterSettings(scriptPath: string): string {
  const hook = {
    type: 'command',
    command: buildLifecycleHookCommand(scriptPath),
    async: true,
    timeout: LIFECYCLE_HOOK_TIMEOUT_SECONDS,
  };
  const settings = {
    hooks: {
      SessionStart: [{ hooks: [hook] }],
      UserPromptSubmit: [{ hooks: [hook] }],
      PostToolUse: [{ matcher: '*', hooks: [hook] }],
      PreToolUse: [{ matcher: CLAUDE_QUESTION_TOOL, hooks: [hook] }],
      PermissionRequest: [{ matcher: '*', hooks: [hook] }],
      Notification: [{ hooks: [hook] }],
      Stop: [{ hooks: [hook] }],
    },
  };
  return JSON.stringify(settings, null, 2) + '\n';
}

/**
 * Write `content` to `path` with mode 0600 through a temp file and a rename,
 * only when it differs from what is there. The mode is enforced either way, so
 * a file left with a wider mode is tightened.
 */
function writeFileIfChanged(path: string, content: string): void {
  let current: string | null = null;
  try {
    current = readFileSync(path, 'utf8');
  } catch {
    current = null;
  }
  if (current === content) {
    chmodSync(path, 0o600);
    return;
  }
  const temp = `${path}.${process.pid}.${randomBytes(4).toString('hex')}.tmp`;
  writeFileSync(temp, content, { mode: 0o600 });
  chmodSync(temp, 0o600);
  renameSync(temp, path);
}

/**
 * Install the reporter script and its settings file, and return the absolute
 * settings path to hand to the harness. Directory mode 0700, files 0600,
 * set explicitly rather than left to the umask. Throws on a filesystem error;
 * callers use `resolveLifecycleReporterInjection`, which fails open.
 */
export function ensureLifecycleReporterInstalled(dir: string = lifecycleReporterDir()): string {
  mkdirSync(dir, { recursive: true, mode: 0o700 });
  chmodSync(dir, 0o700);
  const scriptPath = join(dir, LIFECYCLE_REPORTER_SCRIPT_NAME);
  const settingsPath = join(dir, LIFECYCLE_REPORTER_SETTINGS_NAME);
  writeFileIfChanged(scriptPath, LIFECYCLE_REPORTER_SCRIPT);
  writeFileIfChanged(settingsPath, buildLifecycleReporterSettings(scriptPath));
  return settingsPath;
}

export type LifecycleReporterInjection = ReturnType<NonNullable<HarnessProvider['buildLifecycleReporterInjection']>>;

/**
 * The reporter injection for a launch on `harness`, or null when the harness
 * has no reporter or the files could not be installed. Installs (or refreshes)
 * the files first: the harness refuses to start when its `--settings` file is
 * missing, so the flag is only ever injected right after a successful install.
 * A failure is logged and the agent launches without a reporter, which falls
 * back to today's PTY-silence behavior.
 *
 * The installed files are Claude's (only `CLAUDE_HARNESS` carries the
 * capability). A harness that gains a reporter (#1796) installs its own
 * harness-named files rather than reusing these.
 */
export function resolveLifecycleReporterInjection(
  harness: HarnessProvider,
  dir?: string,
): LifecycleReporterInjection | null {
  if (!harness.buildLifecycleReporterInjection) return null;
  let settingsPath: string;
  try {
    settingsPath = ensureLifecycleReporterInstalled(dir);
  } catch (err) {
    logger.warn(`Lifecycle reporter not installed; launching without it: ${err instanceof Error ? err.message : String(err)}`);
    return null;
  }
  return harness.buildLifecycleReporterInjection(settingsPath);
}
